#include <zephyr/kernel.h>
#include <zephyr/ztest.h>
#include <zephyr/irq_offload.h>

#define STACK_SIZE (512 + CONFIG_TEST_EXTRA_STACK_SIZE)
#define TIMEOUT_MS 500

/*
 * Test k_poll_signal_raise
 */
static K_POLL_SIGNAL_DEFINE(poll_signal_test);
static K_THREAD_STACK_DEFINE(poll_signal_stack, STACK_SIZE);
static struct k_thread poll_signal_thread_data;

static void poll_signal_producer_thread(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    k_msleep(100); /* Give main thread time to set up poll */
    /* The original code likely had 'k_poll_signal_int(&poll_signal_test, 1);' */
    /* FIX: Changed to k_poll_signal_raise as 'k_poll_signal_int' is not a valid API. */
    k_poll_signal_raise(&poll_signal_test, 1);
}

ZTEST(poll_api, test_poll_signal_raise)
{
    struct k_poll_event events[1];
    int ret;

    k_poll_signal_init(&poll_signal_test);
    k_poll_event_init(&events[0], K_POLL_TYPE_SIGNAL, K_POLL_MODE_NOTIFY_ALL, &poll_signal_test);

    k_thread_create(&poll_signal_thread_data, poll_signal_stack, STACK_SIZE,
                    poll_signal_producer_thread, NULL, NULL, NULL,
                    K_PRIO_PREEMPT(0), 0, K_FOREVER);
    k_thread_start(&poll_signal_thread_data);

    ret = k_poll(events, 1, K_MSEC(TIMEOUT_MS));

    zassert_equal(ret, 0, "k_poll failed");
    zassert_equal(events[0].state, K_POLL_STATE_SIGNALED, "Event not signaled");
    zassert_equal(poll_signal_test.result, 1, "Signal result mismatch");
    zassert_equal(poll_signal_test.signaled, 0, "Signal not cleared by k_poll");

    k_thread_abort(&poll_signal_thread_data);
}

/*
 * Test k_poll_sem
 */
static K_SEM_DEFINE(poll_sem, 0, 1);
static K_THREAD_STACK_DEFINE(poll_sem_stack, STACK_SIZE);
static struct k_thread poll_sem_thread_data;

static void poll_sem_producer_thread(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    k_msleep(100);
    k_sem_give(&poll_sem);
}

ZTEST(poll_api, test_poll_sem)
{
    struct k_poll_event events[1];
    int ret;

    k_poll_event_init(&events[0], K_POLL_TYPE_SEM_AVAILABLE, K_POLL_MODE_NOTIFY_ALL, &poll_sem);

    k_thread_create(&poll_sem_thread_data, poll_sem_stack, STACK_SIZE,
                    poll_sem_producer_thread, NULL, NULL, NULL,
                    K_PRIO_PREEMPT(0), 0, K_FOREVER);
    k_thread_start(&poll_sem_thread_data);

    ret = k_poll(events, 1, K_MSEC(TIMEOUT_MS));

    zassert_equal(ret, 0, "k_poll failed");
    zassert_equal(events[0].state, K_POLL_STATE_SEM_AVAILABLE, "Semaphore not available");

    k_thread_abort(&poll_sem_thread_data);
}

/*
 * Test k_poll_queue
 */
static K_MSGQ_DEFINE(poll_msgq, sizeof(int), 1, 4);
static K_THREAD_STACK_DEFINE(poll_msgq_stack, STACK_SIZE);
static struct k_thread poll_msgq_thread_data;

static void poll_msgq_producer_thread(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    k_msleep(100);
    int data = 123;
    k_msgq_put(&poll_msgq, &data, K_FOREVER);
}

ZTEST(poll_api, test_poll_msgq)
{
    struct k_poll_event events[1];
    int ret;
    int received_data;

    k_poll_event_init(&events[0], K_POLL_TYPE_MSGQ_DATA_AVAILABLE, K_POLL_MODE_NOTIFY_ALL, &poll_msgq);

    k_thread_create(&poll_msgq_thread_data, poll_msgq_stack, STACK_SIZE,
                    poll_msgq_producer_thread, NULL, NULL, NULL,
                    K_PRIO_PREEMPT(0), 0, K_FOREVER);
    k_thread_start(&poll_msgq_thread_data);

    ret = k_poll(events, 1, K_MSEC(TIMEOUT_MS));

    zassert_equal(ret, 0, "k_poll failed");
    zassert_equal(events[0].state, K_POLL_STATE_MSGQ_DATA_AVAILABLE, "Message queue data not available");

    ret = k_msgq_get(&poll_msgq, &received_data, K_NO_WAIT);
    zassert_equal(ret, 0, "Failed to get message from queue");
    zassert_equal(received_data, 123, "Received data mismatch");

    k_thread_abort(&poll_msgq_thread_data);
}

/*
 * Test k_poll_timeout
 */
ZTEST(poll_api, test_poll_timeout)
{
    struct k_poll_event events[1];
    int ret;

    k_poll_event_init(&events[0], K_POLL_TYPE_SIGNAL, K_POLL_MODE_NOTIFY_ALL, NULL); // No object, just for timeout

    k_ticks_t start_time = k_uptime_ticks();
    ret = k_poll(events, 1, K_MSEC(100));
    k_ticks_t end_time = k_uptime_ticks();

    zassert_equal(ret, -EAGAIN, "k_poll did not timeout");
    zassert_true(k_ticks_to_ms_floor64(end_time - start_time) >= 90, "Timeout too short");
    zassert_true(k_ticks_to_ms_floor64(end_time - start_time) <= 110, "Timeout too long");
}

/*
 * Test k_poll_multiple_events
 */
static K_POLL_SIGNAL_DEFINE(poll_signal_multi_1);
static K_POLL_SIGNAL_DEFINE(poll_signal_multi_2);
static K_THREAD_STACK_DEFINE(poll_multi_stack, STACK_SIZE);
static struct k_thread poll_multi_thread_data;

static void poll_multi_producer_thread(void *p1, void *p2, void *p3)
{
    ARG_UNUSED(p1);
    ARG_UNUSED(p2);
    ARG_UNUSED(p3);

    k_msleep(100);
    k_poll_signal_raise(&poll_signal_multi_2, 2); // Raise the second signal
}

ZTEST(poll_api, test_poll_multiple_events)
{
    struct k_poll_event events[2];
    int ret;

    k_poll_signal_init(&poll_signal_multi_1);
    k_poll_signal_init(&poll_signal_multi_2);

    k_poll_event_init(&events[0], K_POLL_TYPE_SIGNAL, K_POLL_MODE_NOTIFY_ALL, &poll_signal_multi_1);
    k_poll_event_init(&events[1], K_POLL_TYPE_SIGNAL, K_POLL_MODE_NOTIFY_ALL, &poll_signal_multi_2);

    k_thread_create(&poll_multi_thread_data, poll_multi_stack, STACK_SIZE,
                    poll_multi_producer_thread, NULL, NULL, NULL,
                    K_PRIO_PREEMPT(0), 0, K_FOREVER);
    k_thread_start(&poll_multi_thread_data);

    ret = k_poll(events, 2, K_MSEC(TIMEOUT_MS));

    zassert_equal(ret, 0, "k_poll failed");
    zassert_equal(events[0].state, K_POLL_STATE_NOT_READY, "First event should not be signaled");
    zassert_equal(events[1].state, K_POLL_STATE_SIGNALED, "Second event not signaled");
    zassert_equal(poll_signal_multi_2.result, 2, "Signal result mismatch");

    k_thread_abort(&poll_multi_thread_data);
}

ZTEST_SUITE(poll_api, NULL, NULL, NULL, NULL, NULL);
